// HG-sourced follower species (see FOLLOWER_GRAPHICS_TABLE in src/follower_mon.c and ENTRY P17 in
// Changelog.txt) only have 8 real overworld frames each, not the 16 sWalkBillboardAnims/
// BILLBOARD_FRAME_SEQ_GENERIC_WALK assumes. All 4 entries below deliberately cover the SAME [0,7] range
// (matching hg_tsure_poke.bin's own 8-entry sequence) rather than 4 different direction-specific ranges,
// so this always plays the 8 real frames as one continuous walk loop regardless of which of the 4 entries
// gets selected by facing direction - actual facing is handled separately, by rotating the Billboard
// itself (see FollowerMon_RefreshRotation, src/follower_mon.c), not by swapping to different frame ranges.
// ENTRY P19 (2026-10-01): these 4 ranges are no longer arbitrary/identical (see ENTRY P17's original
// version, and ENTRY P19 in Changelog.txt for the full story of why real rotation - the P17/P18 approach -
// doesn't work for this billboard type at all). Decoded hg_tsure_poke's actual pixel content by hand
// (manual PNG parsing, not a guess) and found a genuine 4-direction x 2-frame structure: frames 0-1 are a
// symmetric back view with no face visible (north/away from camera), frames 2-3 are symmetric with visible
// eyes (south/facing camera), and frames 4-5 / 6-7 are mirror-image asymmetric profile views (west/east,
// exact left/right assignment is the one part of this that's a best guess, not directly measurable from
// pixel data alone - swap the WEST/EAST rows below if the follower turns out to lean the wrong way).
// animNum is used directly as the array index (ov5_021EDF18 in ov5_021EB1A0.c is an identity mapping,
// {0,1,2,3} -> {0,1,2,3}), and animNum itself IS the raw DIR_NORTH/SOUTH/WEST/EAST facing value - so this
// array's row order must match that exactly, not the "whichever order looks natural" order of the other
// per-species anims in this file (which is why this one is commented instead of following the unremarked
// pattern above). Frame counter ranges reuse hg_tsure_poke.bin's existing 8-entry sequence unchanged (its
// thresholds 0/4/8/12/16/20/24/28 -> textureIdx 0-7 already line up exactly with 4 back-to-back 2-frame
// blocks).
